# utils/file_utils.py
"""文件系统工具：项目遍历、MD5 计算、安全读取。"""

import hashlib
import os
from typing import List

from config.settings import settings
from utils.logger import get_logger

logger = get_logger(__name__)


def get_project_files(
    project_root: str,
    supported_suffixes: List[str],
) -> List[str]:
    """递归遍历项目，返回所有支持后缀的文件绝对路径。

    Args:
        project_root: 项目根路径
        supported_suffixes: 如 [".py"]

    Returns:
        文件绝对路径列表
    """
    project_root = os.path.abspath(project_root)
    if not os.path.isdir(project_root):
        logger.error(f"项目路径不存在或不是目录: {project_root}")
        return []

    exclude = set(settings.EXCLUDE_DIRS)
    result: List[str] = []

    for root, dirs, files in os.walk(project_root, topdown=True):
        # 原地过滤，避免进入排除目录
        dirs[:] = [
            d for d in dirs
            if d not in exclude and not d.startswith(".")
        ]
        for fname in files:
            if os.path.splitext(fname)[1] in supported_suffixes:
                result.append(os.path.join(root, fname))

    logger.info(
        f"项目遍历完成 | 路径={project_root} | 找到 {len(result)} 个文件 | 后缀={supported_suffixes}"
    )
    return result


def read_file(file_path: str) -> str:
    """安全读取文件内容，依次尝试 utf-8 → gbk。"""
    for enc in ("utf-8", "gbk"):
        try:
            with open(file_path, "r", encoding=enc) as f:
                return f.read()
        except UnicodeDecodeError:
            continue
        except Exception as e:
            logger.error(f"文件读取失败 | {file_path} | {e}")
            return ""
    logger.warning(f"编码识别失败，跳过文件: {file_path}")
    return ""


def file_md5(file_path: str) -> str:
    """计算文件 MD5 十六进制字符串，文件不存在时返回空串。"""
    if not os.path.isfile(file_path):
        return ""
    h = hashlib.md5()
    with open(file_path, "rb") as f:
        for chunk in iter(lambda: f.read(8192), b""):
            h.update(chunk)
    return h.hexdigest()

# graph/knowledge_graph.py
"""知识图谱核心管理类。

底层使用 networkx.DiGraph 存储图结构（支持图算法）。
同时维护 node_map / relation_map 字典，实现 O(1) ID 查询。

对外接口：
  add_node / add_nodes
  add_relation / add_relations
  get_node / get_nodes_by_name
  get_relations_by_source / get_relations_by_target
  get_call_chain
  remove_file_nodes              ← 增量更新用
  update_file                    ← 增量更新用
  export_to_dict / load_from_dict
"""

from __future__ import annotations

from typing import Dict, List, Optional

import networkx as nx

from schema.enums import NodeTypeEnum, RelationTypeEnum
from schema.models import (
    CallRelation,
    ClassNode,
    DirNode,
    FileNode,
    FunctionNode,
    HasRelation,
    ImportRelation,
    NodeType,
    RelationType,
)
from utils.id_gen import file_id
from utils.logger import get_logger

logger = get_logger(__name__)


class KnowledgeGraph:
    """代码知识图谱：节点 + 关系的统一容器与查询引擎。"""

    def __init__(self, project_root: str) -> None:
        self.project_root = project_root
        self._graph: nx.DiGraph = nx.DiGraph()
        self._node_map: Dict[str, NodeType] = {}
        self._relation_map: Dict[str, RelationType] = {}

    # ═══════════════════════════════════════════════════
    #  写操作
    # ═══════════════════════════════════════════════════

    def add_node(self, node: NodeType) -> None:
        if node.node_id in self._node_map:
            logger.debug(f"节点已存在，覆盖: {node.node_id}")
        self._node_map[node.node_id] = node
        self._graph.add_node(node.node_id, node_type=node.node_type, name=node.name)

    def add_nodes(self, nodes: List[NodeType]) -> None:
        for n in nodes:
            self.add_node(n)

    def add_relation(self, rel: RelationType) -> None:
        if rel.relation_id in self._relation_map:
            logger.debug(f"关系已存在，覆盖: {rel.relation_id}")
        self._relation_map[rel.relation_id] = rel
        self._graph.add_edge(
            rel.source_node_id,
            rel.target_node_id,
            relation_type=rel.relation_type,
            relation_id=rel.relation_id,
        )

    def add_relations(self, rels: List[RelationType]) -> None:
        for r in rels:
            self.add_relation(r)

    # ═══════════════════════════════════════════════════
    #  读操作
    # ═══════════════════════════════════════════════════

    def get_node(self, node_id: str) -> Optional[NodeType]:
        return self._node_map.get(node_id)

    def get_nodes_by_name(
        self,
        name: str,
        node_type: Optional[NodeTypeEnum] = None,
    ) -> List[NodeType]:
        """模糊匹配节点名称（大小写不敏感）。"""
        needle = name.lower()
        return [
            n for n in self._node_map.values()
            if needle in n.name.lower()
            and (node_type is None or n.node_type == node_type)
        ]

    def get_relations_by_source(
        self,
        source_id: str,
        rel_type: Optional[RelationTypeEnum] = None,
    ) -> List[RelationType]:
        return [
            r for r in self._relation_map.values()
            if r.source_node_id == source_id
            and (rel_type is None or r.relation_type == rel_type)
        ]

    def get_relations_by_target(
        self,
        target_id: str,
        rel_type: Optional[RelationTypeEnum] = None,
    ) -> List[RelationType]:
        return [
            r for r in self._relation_map.values()
            if r.target_node_id == target_id
            and (rel_type is None or r.relation_type == rel_type)
        ]

    def get_call_chain(
        self,
        function_node_id: str,
        max_depth: int = 3,
    ) -> Dict:
        """返回函数的上下游调用链（BFS 深度限制）。"""
        downstream = dict(
            nx.dfs_successors(self._graph, function_node_id, depth_limit=max_depth)
        )
        upstream = dict(
            nx.dfs_successors(
                self._graph.reverse(copy=False), function_node_id, depth_limit=max_depth
            )
        )
        return {
            "node_id": function_node_id,
            "downstream": downstream,
            "upstream": upstream,
        }

    # ═══════════════════════════════════════════════════
    #  统计
    # ═══════════════════════════════════════════════════

    @property
    def node_count(self) -> int:
        return len(self._node_map)

    @property
    def relation_count(self) -> int:
        return len(self._relation_map)

    def stats(self) -> Dict:
        """返回图谱统计摘要。"""
        type_counts: Dict[str, int] = {}
        for n in self._node_map.values():
            type_counts[n.node_type] = type_counts.get(n.node_type, 0) + 1
        rel_counts: Dict[str, int] = {}
        for r in self._relation_map.values():
            rel_counts[r.relation_type] = rel_counts.get(r.relation_type, 0) + 1
        return {
            "project_root": self.project_root,
            "total_nodes": self.node_count,
            "total_relations": self.relation_count,
            "node_type_counts": type_counts,
            "relation_type_counts": rel_counts,
        }

    # ═══════════════════════════════════════════════════
    #  增量更新接口（TODO：实现细节在 incremental/updater.py）
    # ═══════════════════════════════════════════════════

    def remove_file_nodes(self, file_abs_path: str) -> None:
        """删除指定文件的所有节点及关联关系（增量更新专用）。

        TODO: 当前为完整实现，后续可优化为批量事务删除。
        """
        fid = file_id(file_abs_path)

        # 收集该文件下所有节点
        to_remove = {
            nid for nid, n in self._node_map.items()
            if nid == fid
            or getattr(n, "file_node_id", None) == fid
        }

        # 删除关联关系
        dead_rels = [
            rid for rid, r in self._relation_map.items()
            if r.source_node_id in to_remove or r.target_node_id in to_remove
        ]
        for rid in dead_rels:
            del self._relation_map[rid]

        # 删除节点
        for nid in to_remove:
            del self._node_map[nid]
        self._graph.remove_nodes_from(to_remove)

        logger.info(f"已删除文件节点 | {file_abs_path} | 节点={len(to_remove)} 关系={len(dead_rels)}")

    def update_file(
        self,
        file_abs_path: str,
        nodes: List[NodeType],
        relations: List[RelationType],
    ) -> None:
        """增量更新单个文件的图谱数据（先删后增）。

        TODO: 后续可加入 diff 对比，避免全量替换。
        """
        self.remove_file_nodes(file_abs_path)
        self.add_nodes(nodes)
        self.add_relations(relations)
        logger.info(f"增量更新完成 | {file_abs_path}")

    # ═══════════════════════════════════════════════════
    #  序列化 / 反序列化
    # ═══════════════════════════════════════════════════

    def export_to_dict(self) -> Dict:
        """导出为可序列化的字典（JSON / pickle 通用）。"""
        return {
            "project_root": self.project_root,
            "nodes": [n.model_dump(mode="json") for n in self._node_map.values()],
            "relations": [r.model_dump(mode="json") for r in self._relation_map.values()],
        }

    def load_from_dict(self, data: Dict) -> None:
        """从 export_to_dict() 输出的字典重建图谱。"""
        self.project_root = data.get("project_root", self.project_root)
        self._node_map.clear()
        self._relation_map.clear()
        self._graph.clear()

        _node_cls_map = {
            NodeTypeEnum.DIR: DirNode,
            NodeTypeEnum.FILE: FileNode,
            NodeTypeEnum.CLASS: ClassNode,
            NodeTypeEnum.FUNCTION: FunctionNode,
        }
        for nd in data.get("nodes", []):
            cls = _node_cls_map.get(nd.get("node_type"))
            if cls:
                self.add_node(cls(**nd))

        _rel_cls_map = {
            RelationTypeEnum.HAS: HasRelation,
            RelationTypeEnum.IMPORT: ImportRelation,
            RelationTypeEnum.CALL: CallRelation,
        }
        for rd in data.get("relations", []):
            cls = _rel_cls_map.get(rd.get("relation_type"))
            if cls:
                self.add_relation(cls(**rd))

        logger.info(
            f"图谱加载完成 | 节点={self.node_count} 关系={self.relation_count}"
        )
